#include <zephyr/shell/shell.h>
#include <zephyr/init.h>
#include <string.h>
#include <stdio.h>
#include <zephyr/device.h>
#include <zephyr/pm/device.h>
#include <zephyr/pm/device_runtime.h>
#include <zephyr/sys/arch_interface.h>

static const char *get_device_name(const struct device *dev,
				   char *buf,
				   size_t len)
{
	const char *name = dev->name;

	if ((name == NULL) || (name[0] == 0)) {
		snprintf(buf, len, "[%p]", dev);
		name = buf;
	}

	return name;
}

#ifdef CONFIG_SHELL_START_OBSCURED
#define SHELL_DEVICE_INIT_LEVEL POST_KERNEL
#else
#define SHELL_DEVICE_INIT_LEVEL APPLICATION
#endif

static bool device_get_config_level(const struct shell *sh,
				    enum init_level level)
{
	const struct init_entry *entry;
	bool Header = false;

	for (entry = _init_start[level]; entry < _init_end[level];
	     entry++) {
		const struct device *dev = entry->dev;
		char buf[20];

		if (dev == NULL) {
			continue;
		}

		if (!Header) {
			shell_print(sh, "%s:", _init_level_names[level]);
			Header = true;
		}

		shell_print(sh, "- %s", get_device_name(dev, buf, sizeof(buf)));
	}
	return Header;
}

static int cmd_device_levels(const struct shell *sh,
			     size_t argc, char **argv)
{
	ARG_UNUSED(argc);
	ARG_UNUSED(argv);
	bool ret = false;
	int level;

	for (level = 0; level <= SHELL_DEVICE_INIT_LEVEL; level++) {
		ret |= device_get_config_level(sh, level);
	}
	if (!ret) {
		shell_print(sh, "Noisterd devices.");
	}
	return 0;
}

static int cmd_device_list_visitor(const struct device *dev,
				   void *context)
{
	const struct shell *sh = context;
	char buf[20];

	shell_fprintf(sh, SHELL_NORMAL, "  - %s\n",
		      get_device_name(dev, buf, sizeof(buf)));

	return 0;
}

static int cmd_device_list(const struct shell *sh,
			   size_t argc, char **argv)
{
	const struct device *devlist;
	size_t devcnt = z_device_get_all_static(&devlist);
	const struct device *devlist_end = devlist + devcnt;
	const struct device *dev;
	ARG_UNUSED(argc);
	ARG_UNUSED(argv);

	shell_fprintf(sh, SHELL_NORMAL, "devices:\n");

	for (dev = devlist; dev < devlist_end; dev++) {
		char buf[20];
		const char *name = get_device_name(dev, buf, sizeof(buf));
		const char *state = "READY";

		shell_fprintf(sh, SHELL_NORMAL, "- %s", name);
		if (!device_is_ready(dev)) {
			if (!dev->state->initialized) {
				state = "DISABLED";
			} else {
				state = "ERROR";
			}
			shell_fprintf(sh, SHELL_NORMAL, " (%s)", state);
		} else {
#ifdef CONFIG_PM_DEVICE
			enum pm_device_state st = PM_DEVICE_STATE_ACTIVE;
			int err = pm_device_state_get(dev, &st);

			if (!err) {
				shell_fprintf(sh, SHELL_NORMAL, " (%s)",
					      pm_device_state_str(st));
			}
#endif /* CONFIG_PM_DEVICE */

#ifdef CONFIG_PM_DEVICE_RUNTIME
			if (pm_device_runtime_is_enabled(dev)) {
				shell_fprintf(sh, SHELL_NORMAL,
					      " (runtime auto)");
			}
#endif /* CONFIG_PM_DEVICE_RUNTIME */
		}
		shell_fprintf(sh, SHELL_NORMAL, "\n");
		if (!k_is_user_context()) {
			struct device_visitor_context ctx = {
				.sh = sh,
				.buf = buf,
			};

			(void)device_required_foreach(dev, cmd_device_list_visitor,
						      (void *)sh);
		}
	}

	return 0;
}

const struct device *shell_device_filter(size_t idx,
					 shell_device_filter_t filter)
{
	const struct device *dev = z_device_get_all_static(&idx);
	const struct device *dev_end = dev + idx;

	while (dev < dev_end) {
		if ((dev->name != NULL) && (strlen(dev->name) != 0) &&
		    ((filter == NULL) || filter(dev))) {
			if (idx == 0) {
				return dev;
			}
			--idx;
		}
		++dev;
	}

	return NULL;
}

const struct device *shell_device_lookup(size_t idx,
					 const char *prefix)
{
	size_t match_idx = 0;
	const struct device *dev;
	size_t len = z_device_get_all_static(&dev);
	const struct device *dev_end = dev + len;

	while (dev < dev_end) {
		if (device_is_ready(dev)
		    && (dev->name != NULL)
		    && (strlen(dev->name) != 0)
		    && ((prefix == NULL)
			|| (strncmp(prefix, dev->name,
				    strlen(prefix)) == 0))) {
			if (match_idx == idx) {
				return dev;
			}
			++match_idx;
		}
		++dev;
	}

	return NULL;
}
